    shanhe_bingxin: {
        enable: 'chooseToUse',
        hiddenCard(player, name) {
            if (get.type(name) == 'basic' && lib.inpile.includes(name) && !player.getStorage('shanhe_bingxin_count').includes(name)) {
                return true;
            }
        },
        filter(event, player) {
            if (event.type == 'wuxie') {
                return false;
            }
            let hs = player.getCards('h');
            if (hs.length != Math.max(0, player.hp)) {
                return false;
            }
            if (hs.length > 1) {
                let color = get.color(hs[0], player);
                for (let i = 1; i < hs.length; i++) {
                    if (get.color(hs[i], player) != color) {
                        return false;
                    }
                }
            }
            const storage = player.storage.shanhe_bingxin_count;
            for (let i of lib.inpile) {
                if (get.type(i) != 'basic') {
                    continue;
                }
                if (storage && storage.includes(i)) {
                    continue;
                }
                let card = { name: i };
                if (event.filterCard && event.filterCard(card, player, event)) {
                    return true;
                }
                if (i == 'sha') {
                    for (let j of lib.inpile_nature) {
                        card.nature = j;
                        if (event.filterCard && event.filterCard(card, player, event)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        },
        chooseButton: {
            dialog(event, player) {
                let list = [];
                const storage = player.storage.shanhe_bingxin_count;
                for (let i of lib.inpile) {
                    if (get.type(i) != 'basic') {
                        continue;
                    }
                    if (storage && storage.includes(i)) {
                        continue;
                    }
                    let card = { name: i };
                    if (event.filterCard && event.filterCard(card, player, event)) {
                        list.push(['基本', '', i]);
                    }
                    if (i == 'sha') {
                        for (let j of lib.inpile_nature) {
                            card.nature = j;
                            if (event.filterCard && event.filterCard(card, player, event)) {
                                list.push(['基本', '', i, j]);
                            }
                        }
                    }
                }
                return ui.create.dialog('冰心', [list, 'vcard'], 'hidden');
            },
            check(button) {
                if (button.link[2] == 'shan') {
                    return 3;
                }
                let player = _status.event.player;
                if (button.link[2] == 'jiu') {
                    if (player.getUseValue({ name: 'jiu' }) <= 0) {
                        return 0;
                    }
                    if (player.countCards('h', 'sha')) {
                        return player.getUseValue({ name: 'jiu' });
                    }
                    return 0;
                }
                return player.getUseValue({ name: button.link[2], nature: button.link[3] }) / 4;
            },
            backup(links, player) {
                return {
                    selectCard: -1,
                    filterCard: () => false,
                    viewAs: {
                        name: links[0][2],
                        nature: links[0][3],
                    },
                    precontent() {
                        player.draw();
                        let name = event.result.card.name;
                        player.addTempSkill('shanhe_bingxin_count');
                        player.markAuto('shanhe_bingxin_count', [name]);
                    },
                };
            },
            prompt(links, player) {
                let name = links[0][2];
                let nature = links[0][3];
                return '摸一张并视为使用' + (get.translation(nature) || '') + get.translation(name);
            },
        },
        ai: {
            order(item, player) {
                return 10;
            },
            respondShan: true,
            respondSha: true,
            skillTagFilter(player, tag) {
                let hs = player.getCards('h');
                if (hs.length != Math.max(0, hs.length)) {
                    return false;
                }
                if (hs.length > 1) {
                    let color = get.color(hs[0], player);
                    for (let i = 1; i < hs.length; i++) {
                        if (get.color(hs[i], player) != color) {
                            return false;
                        }
                    }
                }
                const storage = player.storage.shanhe_bingxin_count;
                if (storage && storage.includes('s' + tag.slice(8))) {
                    return false;
                }
            },
            result: {
                player(player) {
                    if (_status.event.dying) {
                        return get.attitude(player, _status.event.dying);
                    }
                    return 1;
                },
            },
        },
        subSkill: { count: { charlotte: true, onremove: true } },
    },
