    shanhe_tuntian: {
        trigger: {
            player: 'loseAfter',
            global: ['equipAfter', 'addJudgeAfter', 'gainAfter', 'loseAsyncAfter', 'addToExpansionAfter'],
        },
        forced: true,
        filter(event, player) {
            if (player == _status.currentPhase) {
                return false;
            }
            if (event.name == 'gain' && event.player == player) {
                return false;
            }
            let evt = event.getl(player);
            return evt && evt.cards2 && evt.cards2.length;
        },
        content() {
            'step 0';
            const next = player.judge(function (card) {
                if (card.suit == 'heart') {
                    return -1;
                }
                return 1;
            });
            next.judge2 = function (result) {
                return result.bool;
            };
            if (get.mode() != 'guozhan') {
                next.callback = lib.skill.shanhe_tuntian.callback;
                event.finish();
            }
            ('step 1');
            if (!result.bool || get.position(result.card) != 'd') {
                event.finish();
                return;
            }
            event.card = result.card;
            player.chooseBool('是否将' + get.translation(event.card) + '作为<田>置于武将牌上？').ai = function () {
                return true;
            };
            ('step 2');
            if (!result.bool && !event.directbool) {
                return;
            }
            player.addToExpansion(event.card, 'gain2').gaintag.add('shanhe_tuntian');
        },
        callback() {
            if (!event.judgeResult.bool) {
                event.finish();
                return;
            }
            player.addToExpansion(event.judgeResult.card, 'gain2').gaintag.add('shanhe_tuntian');
        },
        marktext: '田',
        intro: {
            content: 'expansion',
            markcount: 'expansion',
        },
        onremove(player, skill) {
            let cards = player.getExpansions(skill);
            if (cards.length) {
                player.loseToDiscardpile(cards);
            }
        },
        group: 'shanhe_tuntian_dist',
        subSkill: {
            dist: {
                mod: {
                    globalFrom(from, to, distance) {
                        let num = distance - from.getExpansions('shanhe_tuntian').length;
                        if (_status.event.skill == 'jixi_backup' || _status.event.skill == 'gzjixi_backup') {
                            num++;
                        }
                        return num;
                    },
                },
            },
        },
        ai: {
            effect: {
                target(card, player, target, current) {
                    if (
                        typeof card === 'object' &&
                        card.name === 'sha' &&
                        target.mayHaveShan(
                            player,
                            'use',
                            target.getCards((i) => {
                                return i.hasGaintag('sha_notshan');
                            }),
                        )
                    ) {
                        return [0.6, 0.75];
                    }
                    if (!target.hasFriend() && !player.hasUnknown()) {
                        return;
                    }
                    if (_status.currentPhase == target || get.type(card) === 'delay') {
                        return;
                    }
                    if (card.name != 'shuiyanqijunx' && get.tag(card, 'loseCard') && target.countCards('he')) {
                        if (target.hasSkill('ziliang')) {
                            return 0.7;
                        }
                        return [0.5, Math.max(2, target.countCards('h'))];
                    }
                    if (target.isUnderControl(true, player)) {
                        if ((get.tag(card, 'respondSha') && target.countCards('h', 'sha')) || (get.tag(card, 'respondShan') && target.countCards('h', 'shan'))) {
                            if (target.hasSkill('ziliang')) {
                                return 0.7;
                            }
                            return [0.5, 1];
                        }
                    } else if (get.tag(card, 'respondSha') || get.tag(card, 'respondShan')) {
                        if (get.attitude(player, target) > 0 && card.name == 'juedou') {
                            return;
                        }
                        if (get.tag(card, 'damage') && target.hasSkillTag('maixie')) {
                            return;
                        }
                        if (target.countCards('h') == 0) {
                            return 2;
                        }
                        if (target.hasSkill('ziliang')) {
                            return 0.7;
                        }
                        if (get.mode() == 'guozhan') {
                            return 0.5;
                        }
                        return [0.5, Math.max(target.countCards('h') / 4, target.countCards('h', 'sha') + target.countCards('h', 'shan'))];
                    }
                },
            },
            threaten(player, target) {
                if (target.countCards('h') == 0) {
                    return 2;
                }
                return 0.5;
            },
            nodiscard: true,
        },
    },
