    shanhe_jianying: {
        mod: {
            aiOrder(player, card, num) {
                if (typeof card == 'object' && player.isPhaseUsing()) {
                    let evt = player.getLastUsed();
                    if (evt && evt.card && ((evt.card.suit && evt.card.suit == card.suit) || (evt.card.number && evt.card.number == card.number))) {
                        return num + 10;
                    }
                }
            },
        },
        trigger: { player: 'useCard' },
        forced: true,
        filter(event, player) {
            let evt = player.getLastUsed(1);
            if (!evt || !evt.card) {
                return false;
            }
            if (!player.isPhaseUsing()) {
                return false;
            }
            const evt2 = evt.getParent('phaseUse');
            if (!evt2 || evt2.name != 'phaseUse' || evt2.player != player) {
                return false;
            }
            return (evt.card.suit != 'none' && evt.card.suit == event.card.suit) || (typeof evt.card.number == 'number' && evt.card.number == event.card.number);
        },
        content() {
            player.draw();
        },
        group: 'shanhe_jianying_mark',
        init(player) {
            if (player.isPhaseUsing()) {
                let evt = _status.event.getParent('phaseUse');
                const history = player.getHistory('useCard', function (evt2) {
                    return evt2.getParent('phaseUse') == evt;
                });
                if (history.length) {
                    const trigger = history[history.length - 1];
                    if (trigger.card.suit == 'none' || typeof trigger.card.number != 'number') {
                        return;
                    }
                    player.storage.shanhe_jianying_mark = trigger.card;
                    player.markSkill('shanhe_jianying_mark');
                    game.broadcastAll(
                        function (player, suit) {
                            if (player.marks.shanhe_jianying_mark) {
                                player.marks.shanhe_jianying_mark.firstChild.innerHTML = get.translation(suit);
                            }
                        },
                        player,
                        trigger.card.suit,
                    );
                    player.when('phaseUseAfter').then(() => {
                        player.unmarkSkill('shanhe_jianying_mark');
                        delete player.storage.shanhe_jianying_mark;
                    });
                }
            }
        },
        onremove(player) {
            player.unmarkSkill('shanhe_jianying_mark');
            delete player.storage.shanhe_jianying_mark;
            player.update();
        },
        subSkill: {
            mark: {
                charlotte: true,
                trigger: { player: 'useCard1' },
                filter(event, player) {
                    return player.isPhaseUsing();
                },
                forced: true,
                popup: false,
                firstDo: true,
                content() {
                    if (trigger.card.suit == 'none' || typeof trigger.card.number != 'number') {
                        player.unmarkSkill('shanhe_jianying_mark');
                    } else {
                        player.storage.shanhe_jianying_mark = trigger.card;
                        player.markSkill('shanhe_jianying_mark');
                        game.broadcastAll(
                            function (player, suit) {
                                if (player.marks.shanhe_jianying_mark) {
                                    player.marks.shanhe_jianying_mark.firstChild.innerHTML = get.translation(suit);
                                }
                            },
                            player,
                            trigger.card.suit,
                        );
                        player.when('phaseUseAfter').then(() => {
                            player.unmarkSkill('shanhe_jianying_mark');
                            delete player.storage.shanhe_jianying_mark;
                        });
                    }
                },
                intro: {
                    markcount(card, player) {
                        let num = card.number;
                        let list = [1, 11, 12, 13];
                        if (list.includes(num)) {
                            return ['A', 'J', 'Q', 'K'][list.indexOf(num)];
                        }
                        return parseFloat(num);
                    },
                    content(storage, player) {
                        const suit = storage.suit;
                        let num = storage.number;
                        let str = '<li>上一张牌的花色:' + get.translation(suit);
                        str += '<br><li>上一张牌的点数:';
                        let list = [1, 11, 12, 13];
                        if (list.includes(num)) {
                            str += ['A(1)', 'J(11)', 'Q(12)', 'K(13)'][list.indexOf(num)];
                        } else {
                            str += parseFloat(num);
                        }
                        return str;
                    },
                },
            },
        },
    },
