    hulao_pindao: {
        trigger: {
            target: 'useCardToTargeted',
        },
        forced: true,
        filter(event, player) {
            return player.countCards('h', 'sha') > 0 && event.card.name == 'sha' && typeof event.card.number == 'number' && event.player != player && player.getEnemies().includes(event.player);
        },
        content() {
            'step 0';
            player
                .chooseCard('h', '是否打出一张【杀】与' + get.translation(trigger.player) + '拼刀？', function (card, player) {
                    return card.name == 'sha';
                })
                .set('ai', function (card) {
                    if (-3 <= card.number - trigger.card.number <= 3) {
                        return true;
                    } else {
                        return false;
                    }
                });
            ('step 1');
            if (result.bool) {
                player.respond(result.cards, 'hulao_pindao', 'highlight', 'noOrdering');
            } else {
                event.finish();
            }
            ('step 2');
            player.judge(function (card) {
                if (result.cards[0].number - trigger.card.number > 0) {
                    event.num = result.cards[0].number - trigger.card.number;
                } else {
                    event.num = -(result.cards[0].number - trigger.card.number);
                }
                return card.number >= event.num ? 2 : -1;
            });
            ('step 3');
            if (result.judge > 0) {
                trigger.parent.excluded.add(player);
                game.log(trigger.card, '对', player, '无效');
                trigger.player.damage(3);
            } else {
                trigger.directHit.addArray(game.players);
                game.log(trigger.card, '无法被', game.players, '抵消');
            }
        },
    },
