    huoshao_qice: {
        group: ['huoshao_qice_draw'],
        enable: 'phaseUse',
        audio: 'reqice',
        filter(event, player) {
            let hs = player.getCards('h');
            if (!hs.length) {
                return false;
            }
            if ((player.getStat('skill').huoshao_qice || 0) >= player.countMark('huoshao_qice_mark') + 1) {
                return false;
            }
            for (let i = 0; i < hs.length; i++) {
                const mod2 = game.checkMod(hs[i], player, 'unchanged', 'cardEnabled2', player);
                if (mod2 === false) {
                    return false;
                }
            }
            return true;
        },
        chooseButton: {
            dialog(event, player) {
                let list = [];
                for (let i = 0; i < lib.inpile.length; i++) {
                    if (get.type(lib.inpile[i]) == 'trick') {
                        list.push(['锦囊', '', lib.inpile[i]]);
                    }
                }
                return ui.create.dialog(get.translation('huoshao_qice'), [list, 'vcard']);
            },
            filter(button, player) {
                return lib.filter.filterCard({ name: button.link[2] }, player, _status.event.parent);
            },
            check(button) {
                let player = _status.event.player;
                let recover = 0, lose = 1, gain = 0, players = game.filterPlayer();
                for (let i of players) {
                    if (i.hp == 1 && get.damageEffect(i, player, player) > 0 && !i.hasSha() && (player.getStat('skill').huoshao_qice || 0) < player.countMark('huoshao_qice_mark') + 1) {
                        return button.link[2] == 'juedou' ? 2 : -1;
                    }
                    if (!i.isOut()) {
                        if (i.hp < i.maxHp) {
                            if (get.attitude(player, i) > 0) {
                                if (i.hp < 2) {
                                    lose--;
                                    recover += 0.5;
                                }
                                lose--;
                                recover++;
                            } else if (get.attitude(player, i) < 0) {
                                if (i.hp < 2) {
                                    lose++;
                                    recover -= 0.5;
                                }
                                lose++;
                                recover--;
                            }
                        } else {
                            if (get.attitude(player, i) > 0) {
                                lose--;
                            } else if (get.attitude(player, i) < 0) {
                                lose++;
                            }
                        }
                        if (get.attitude(player, i) > 0) {
                            gain++;
                        } else if (get.attitude(player, i) < 0) {
                            gain--;
                        }
                    }
                }
                if (lose > recover && lose > 0 && (player.getStat('skill').huoshao_qice || 0) < player.countMark('huoshao_qice_mark') + 1) {
                    return button.link[2] == 'nanman' || button.link[2] == 'wanjian' ? 1 : -1;
                }
                if (lose < recover && recover > 0 && (player.getStat('skill').huoshao_qice || 0) < player.countMark('huoshao_qice_mark') + 1) {
                    return button.link[2] == 'taoyuan' ? 1 : -1;
                } else {
                    if (gain > 0 && (player.getStat('skill').huoshao_qice || 0) < player.countMark('huoshao_qice_mark') + 1) {
                        return button.link[2] == 'wugu' ? 1 : -1;
                    } else {
                        let effect = player.getUseValue(button.link[2]);
                        if (player.countCards('hs', button.link[2]) > 0 || button.link[2] == 'huogong') {
                            return 0;
                        }
                        if ((player.getStat('skill').huoshao_qice || 0) < player.countMark('huoshao_qice_mark') + 1) {
                            if (['draw', 'gain', 'multineg'].some((i) => get.tag(button.link[2], i) >= 1)) {
                                return effect * 99999;
                            }
                        }
                        if (effect > 0) {
                            return effect;
                        }
                        return 0;
                    }
                }
            },
            backup(links, player) {
                return {
                    filterCard: true,
                    selectCard: -1,
                    position: 'h',
                    audio: 'reqice',
                    popname: true,
                    viewAs: { name: links[0][2] },
                };
            },
            prompt(links, player) {
                return '将所有手牌当【' + get.translation(links[0][2]) + '】使用';
            },
        },
        ai: {
            order: 1,
            result: {
                player(player) {
                    let num = 0;
                    let cards = player.getCards('h');
                    if (cards.length > Math.max(3 + (player.countMark('huoshao_qice_mark') > 0 ? 2 : 0), Math.max(3 + player.countMark('huoshao_qice_mark'), game.players.length + 1)) && (player.getStat('skill').huoshao_qice || 0) == player.countMark('huoshao_qice_mark')) {
                        return 0;
                    }
                    if (Array.isArray(cards)) {
                        for (let i of cards) {
                            num += Math.max(0, get.value(i, player, 'raw'));
                        }
                    }
                    num /= cards.length;
                    num /= (player.countMark('huoshao_qice_mark') + 1) * 1.3;
                    num *= Math.min(cards.length, player.hp);
                    return 15 + player.countMark('huoshao_qice_mark') - num;
                },
            },
            threaten: 1.7,
        },
        subSkill: {
            bakcup: { audio: 'qice_backup' },
            draw: {
                trigger: { player: 'useCardAfter' },
                forced: true,
                charlotte: true,
                popup: false,
                filter(event, player) {
                    return event.skill == 'huoshao_qice_backup';
                },
                content() {
                    player.draw(trigger.targets.length);
                },
            },
            mark: {
                charlotte: true,
                intro: {
                    name2: '奇策',
                    content: 'mark',
                },
            },
        },
    },
