    fenghuo_qinyin: {
        trigger: { player: 'phaseDiscardEnd' },
        forced: true,
        filter(event, player) {
            let cards = [];
            player.getHistory('lose', function (evt) {
                if (evt.type == 'discard' && evt.getParent('phaseDiscard') == event) {
                    cards.addArray(evt.cards2);
                }
            });
            return cards.length > 1;
        },
        content() {
            'step 0';
            event.forceDie = true;
            if (typeof event.count != 'number') {
                event.count = 1;
            }
            let recover = 0, lose = 0, players = game.filterPlayer();
            for (let i of players) {
                if (i.hp < i.maxHp) {
                    if (get.attitude(player, i) > 0) {
                        if (i.hp < 2) {
                            lose--;
                            recover += 0.5;
                        }
                        lose--;
                        recover++;
                    } else if (get.attitude(player, i) < 0) {
                        if (i.hp < 2) {
                            lose++;
                            recover -= 0.5;
                        }
                        lose++;
                        recover--;
                    }
                } else {
                    if (get.attitude(player, i) > 0) {
                        lose--;
                    } else if (get.attitude(player, i) < 0) {
                        lose++;
                    }
                }
            }
            let prompt = get.prompt('fenghuo_qinyin') + '(剩余' + get.cnNumber(event.count) + '次)';
            player.chooseControl('失去体力', '回复体力', 'cancel2', ui.create.dialog(get.prompt('fenghuo_qinyin'), 'hidden')).ai = function () {
                if (lose > recover && lose > 0) {
                    return 0;
                }
                if (lose < recover && recover > 0) {
                    return 1;
                }
                return 2;
            };
            ('step 1');
            if (result.control == 'cancel2') {
                event.finish();
            } else {
                event.bool = result.control == '回复体力';
                event.num = 0;
                event.players = game.filterPlayer();
            }
            ('step 2');
            if (event.num < event.players.length) {
                const target = event.players[event.num];
                if (event.bool) {
                    target.recover();
                } else {
                    target.loseHp();
                }
                event.num++;
                event.redo();
            }
            ('step 3');
            if (event.count > 1) {
                event.count--;
                event.goto(0);
            }
        },
        ai: {
            expose: 0.1,
            threaten: 2,
        },
    },
