    fenghuo_qiaoshui: {
        enable: 'phaseUse',
        filterTarget(card, player, target) {
            return player.canCompare(target);
        },
        filter(event, player) {
            return player.countCards('h') > 0;
        },
        content() {
            'step 0';
            player.chooseToCompare(target);
            ('step 1');
            if (result.bool) {
                player.addTempSkill('fenghuo_qiaoshui3', 'phaseUseEnd');
            } else {
                player.addTempSkill('fenghuo_qiaoshui4');
                event.getParent(3).skipped = true;
            }
        },
        ai: {
            order(item, player) {
                if (
                    player.countCards('h', function (card) {
                        return player.hasValueTarget(card);
                    })
                ) {
                    return 10;
                }
                return 1;
            },
            result: {
                target(player, target) {
                    if (
                        player.countCards('h', function (card) {
                            return player.hasValueTarget(card);
                        })
                    ) {
                        if (player.hasSkill('fenghuo_qiaoshui3')) {
                            return 0;
                        }
                        const nd = !player.needsToDiscard();
                        if (
                            player.hasCard(function (card) {
                                if (get.position(card) != 'h') {
                                    return false;
                                }
                                let val = get.value(card);
                                if (nd && val < 0) {
                                    return true;
                                }
                                if (val <= 5) {
                                    return card.number >= 12;
                                }
                                if (val <= 6) {
                                    return card.number >= 13;
                                }
                                return false;
                            })
                        ) {
                            return -1;
                        }
                        return 0;
                    }
                    return -1;
                },
            },
        },
    },
    fenghuo_qiaoshui3: {
        trigger: { player: 'useCard2' },
        forced: true,
        filter(event, player) {
            const type = get.type(event.card);
            return type == 'basic' || type == 'trick';
        },
        content() {
            'step 0';
            player.removeSkill('fenghuo_qiaoshui3');
            let goon = false;
            const info = get.info(trigger.card);
            if (trigger.targets && !info.multitarget) {
                const players = game.filterPlayer();
                for (let i of players) {
                    if (lib.filter.targetEnabled2(trigger.card, player, i) && !trigger.targets.includes(i)) {
                        goon = true;
                        break;
                    }
                }
            }
            if (goon) {
                player
                    .chooseTarget('巧说:是否额外指定一名' + get.translation(trigger.card) + '的目标？', function (card, player, target) {
                        const trigger = _status.event;
                        if (trigger.targets.includes(target)) {
                            return false;
                        }
                        return lib.filter.targetEnabled2(trigger.card, _status.event.player, target);
                    })
                    .set('ai', function (target) {
                        const trigger = _status.event.getTrigger();
                        let player = _status.event.player;
                        return get.effect(target, trigger.card, player, player);
                    })
                    .set('targets', trigger.targets)
                    .set('card', trigger.card);
            } else {
                if (!info.multitarget && trigger.targets && trigger.targets.length > 1) {
                    event.goto(3);
                }
            }
            ('step 1');
            if (result.bool) {
                event.target = result.targets[0];
            } else {
                event.finish();
            }
            ('step 2');
            if (event.target) {
                trigger.targets.add(event.target);
            }
            event.finish();
            ('step 3');
            player
                .chooseTarget('巧说:是否减少一名' + get.translation(trigger.card) + '的目标？', function (card, player, target) {
                    return _status.event.targets.includes(target);
                })
                .set('ai', function (target) {
                    const trigger = _status.event.getTrigger();
                    return -get.effect(target, trigger.card, trigger.player, _status.event.player);
                })
                .set('targets', trigger.targets);
            ('step 4');
            if (result.bool) {
                event.targets = result.targets;
                if (event.isMine()) {
                    event.finish();
                }
                for (let i = 0; i < result.targets.length; i++) {
                    trigger.targets.remove(result.targets[i]);
                }
            } else {
                event.finish();
            }
            ('step 5');
        },
    },
