    nianshou_zhuguo_jiawei: {
        enable: 'phaseUse',
        filter(event, player) {
            if (!player.storage.nianshou_zhuguo_skill) {
                player.storage.nianshou_zhuguo_skill = [];
            }
            return !player.hasSkill('nianshou_xiongqu') && player.storage.nianshou_zhuguo > 2;
        },
        check(event, player) {
            return !player.storage.nianshou_zhuguo_skill || player.storage.nianshou_zhuguo_skill.length < 3 + player.countMark('nianshou_zhuguo_jiawei_extra');
        },
        charlotte: true,
        firstDo: true,
        popup: false,
        ruleSkill: true,
        content() {
            'step 0';
            game.countPlayer(function (current) {
                if (current == player || player.getFriends().includes(current)) {
                    lib.skill.nianshou_zhuguo.change(current, -3);
                }
            });
            let list = [];
            for (let i in lib.character) {
                if (lib.character[i][4].includes('boss')) {
                    continue;
                }
                if (i.includes('zuoci')) {
                    continue;
                }
                list.push(i);
            }
            if (!event.skills) {
                event.skills = [];
                for (let i of list) {
                    event.skills.addArray(
                        (lib.character[i][3] || []).filter(function (skill) {
                            const info = get.info(skill);
                            return info && !info.charlotte && lib.translate[skill + '_info'] && !get.skillInfoTranslation(skill, player).length == 0;
                        }),
                    );
                }
            }
            ('step 1');
            const skills = event.skills;
            skills.randomSort();
            let list = [];
            for (let i = 0; i < skills[i].length; i++) {
                if (!player.storage.nianshou_zhuguo_skill.includes(skills[i]) && !list.includes(skills[i]) && !player.getSkills(null, false, false).includes(skills[i]) && lib.translate[skills[i] + '_info'] && !get.skillInfoTranslation(skills[i], player).length == 0) {
                    list.push(skills[i]);
                }
                if (list.length == 3) {
                    break;
                }
            }
            if (!list.length) {
                event.finish();
                return;
            }
            if (player.storage.nianshou_zhuguo > 0) {
                list.push('刷新');
            }
            event.list = list;
            player
                .chooseControl(list)
                .set(
                    'choiceList',
                    list.map(function (i) {
                        return '<div class="skill">【' + get.translation(lib.translate[i + '_ab'] || get.translation(i).slice(0, 2)) + '】</div><div>' + get.skillInfoTranslation(i, player) + '</div>';
                    }),
                )
                .set('displayIndex', false)
                .set('prompt', '假威:请选择一个技能并获得(最多拥有' + get.translation(3 + player.countMark('nianshou_zhuguo_jiawei_extra')) + '个技能)')
                .set('ai', () => {
                    let list = _status.event.controls.slice();
                    return list.sort((a, b) => {
                        return (get.skillRank(b, 'in') - get.skillRank(a, 'in')) * get.attitude(_status.event.player, _status.event.parent.player);
                    })[0];
                });
            ('step 2');
            if (result.control == '刷新') {
                for (let i = 0; i < event.list.length; i++) {
                    event.skills.remove(event.list[i]);
                }
                lib.skill.nianshou_zhuguo.change(player, -1);
                event.goto(1);
                return;
            } else {
                event.skill = result.control;
                player.storage.nianshou_zhuguo_skill.push(event.skill);
                player.addSkill(event.skill);
                player.popup(event.skill);
                game.log(player, '获得了技能', '【', event.skill, '】');
                player.update();
            }
            ('step 3');
            if (player.storage.nianshou_zhuguo_skill.length > 3 + player.countMark('nianshou_zhuguo_jiawei_extra')) {
                player.chooseControl(player.storage.nianshou_zhuguo_skill).prompt = '选择失去1个已有技能';
            } else {
                event.finish();
            }
            ('step 4');
            if (result.control) {
                player.storage.nianshou_zhuguo_skill.remove(result.control);
                player.removeSkill(result.control);
                player.popup(result.control);
                game.log(player, '失去了技能', '【', result.control, '】');
                player.update();
            }
            if (player.storage.nianshou_zhuguo_skill.length > 3 + player.countMark('nianshou_zhuguo_jiawei_extra')) {
                event.goto(3);
            }
        },
        subSkill: {
            extra: {
                charlotte: true,
                marktext: '假威',
                intro: {
                    name2: '假威',
                    content: '本局游戏额外获得#个技能槽',
                },
            },
        },
        ai: {
            order: 10,
            result: {
                player(player) {
                    return !player.storage.nianshou_zhuguo_skill || player.storage.nianshou_zhuguo_skill.length < 3 + player.countMark('nianshou_zhuguo_jiawei_extra') ? 1 : 0;
                },
            },
        },
    },
